package ro.leo.visual;
import android.app.*;import android.content.*;import android.graphics.*;import android.media.*;import android.media.audiofx.Visualizer;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;
/** Functional checks using a locally generated tone, owned files and restored volume. */
public final class RetroTests extends Instrumentation {
    private void check(boolean v,String why){if(!v)throw new AssertionError(why);}
    private Object field(Object o,String name)throws Exception{java.lang.reflect.Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}
    private void main(Runnable r){runOnMainSync(r);waitForIdleSync();}
    private Activity open(Class<?> type,Uri data){Activity a=startActivitySync(new Intent(getTargetContext(),type).setData(data).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));for(int i=0;i<50&&!a.hasWindowFocus();i++)SystemClock.sleep(100);check(a.hasWindowFocus(),"focus "+type.getSimpleName());return a;}
    public void onCreate(Bundle b){start();}
    public void onStart(){Bundle result=new Bundle();final Context c=getTargetContext();final AudioManager audio=(AudioManager)c.getSystemService(Context.AUDIO_SERVICE);int oldVolume=audio.getStreamVolume(AudioManager.STREAM_MUSIC);byte[] wallpaper=null;boolean had=Appearance.wallpaper(c).isFile();TerminalSession shell=null;Activity activity=null;
        try{
            if(had){try(FileInputStream in=new FileInputStream(Appearance.wallpaper(c));ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buf=new byte[4096];int n;while((n=in.read(buf))>0)out.write(buf,0,n);wallpaper=out.toByteArray();}}
            check(Appearance.THEMES.length==9&&Appearance.COLORS.length==9,"nine complete themes");check(AppCatalog.NAMES.length==28&&AppCatalog.parse("23,4,4")[0]==23,"terminal stable ID and order migration");
            HashSet<Integer> colors=new HashSet<Integer>();for(int i=0;i<4;i++){StockWallpapers.apply(c,i);Bitmap b=BitmapFactory.decodeFile(Appearance.wallpaper(c).getPath());check(b!=null&&b.getWidth()==240&&b.getHeight()==302,"stock wallpaper PNG");colors.add(b.getPixel(120,20));b.recycle();}check(colors.size()==4,"distinct wallpaper artwork");
            final StringBuilder transcript=new StringBuilder();shell=new TerminalSession();shell.start(c.getFilesDir(),new TerminalSession.Output(){public void text(String s){synchronized(transcript){transcript.append(s);}}});shell.send("printf 'LEO_READY\\n'; cd /; printf 'LEO_CWD='; pwd");for(int i=0;i<50;i++){synchronized(transcript){if(transcript.toString().contains("LEO_CWD=/\n"))break;}SystemClock.sleep(100);}shell.send("printf 'LEO_PERSIST='; pwd; id");boolean persistent=false;for(int i=0;i<50;i++){synchronized(transcript){persistent=transcript.toString().contains("LEO_PERSIST=/\n")&&transcript.toString().contains("uid=");}if(persistent)break;SystemClock.sleep(100);}check(persistent,"shell executes commands and preserves cd");shell.close();shell=null;
            activity=open(CalculatorActivity.class,null);sendKeyDownUpSync(KeyEvent.KEYCODE_1);sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_UP);sendKeyDownUpSync(KeyEvent.KEYCODE_2);sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_CENTER);waitForIdleSync();check("3".equals(field(activity,"expression")),"retro calculator 1+2=3");
            activity=open(TerminalActivity.class,null);final EditText command=(EditText)field(activity,"command");sendKeyDownUpSync(KeyEvent.KEYCODE_7);sendKeyDownUpSync(KeyEvent.KEYCODE_9);sendKeyDownUpSync(KeyEvent.KEYCODE_3);SystemClock.sleep(900);check("pwd".equals(command.getText().toString()),"physical multitap enters pwd");sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_CENTER);boolean pwd=false;for(int i=0;i<50;i++){waitForIdleSync();String s=((TextView)field(activity,"output")).getText().toString();pwd=s.contains("/data/user/")||s.contains("/data/data/");if(pwd)break;SystemClock.sleep(100);}check(pwd,"keypad OK executes terminal command");
            activity=open(QuickSettingsActivity.class,null);final Activity quick=activity;final java.lang.reflect.Method levels=QuickSettingsActivity.class.getDeclaredMethod("volumes",int.class);levels.setAccessible(true);main(new Runnable(){public void run(){try{levels.invoke(quick,0);}catch(Exception e){throw new RuntimeException(e);}}});int base=audio.getStreamVolume(AudioManager.STREAM_MUSIC),max=audio.getStreamMaxVolume(AudioManager.STREAM_MUSIC);int key=base==max?KeyEvent.KEYCODE_DPAD_LEFT:KeyEvent.KEYCODE_DPAD_RIGHT;sendKeyDownUpSync(key);waitForIdleSync();check(audio.getStreamVolume(AudioManager.STREAM_MUSIC)==base+(base==max?-1:1),"quick settings changes actual music volume");
            audio.setStreamVolume(AudioManager.STREAM_MUSIC,Math.min(2,max),0);
            activity=open(MediaActivity.class,Uri.fromFile(new File("/data/local/tmp/leo-spectrum-test.wav")));boolean signal=false;for(int i=0;i<100;i++){Object face=field(activity,"face");if(face!=null){float[] bands=(float[])field(face,"spectrum");for(float band:bands)if(band>.05f)signal=true;}if(signal)break;SystemClock.sleep(100);}check(signal,"real FFT receives nonzero test audio");final MusicFace face=(MusicFace)field(activity,"face");main(new Runnable(){public void run(){PlaybackService.instance.toggle();face.tick();}});check(!PlaybackService.instance.playing(),"music OK/pause backend");Visualizer visualizer=(Visualizer)field(face,"visualizer");check(visualizer!=null&&!visualizer.getEnabled(),"visualizer disabled on pause");activity=open(CalculatorActivity.class,null);check(field(face,"visualizer")==null,"visualizer released in background");
            result.putString("result","PASS nine themes, four distinct saved wallpapers, terminal shell/cd, physical keypad pwd + execute, Calculator 1+2=3, actual quick volume change, real FFT audio + pause/background release");
        }catch(Throwable e){result.putString("error",android.util.Log.getStackTraceString(e));}
        finally{if(shell!=null)shell.close();c.stopService(new Intent(c,PlaybackService.class));audio.setStreamVolume(AudioManager.STREAM_MUSIC,oldVolume,0);try{if(had&&wallpaper!=null){try(FileOutputStream out=new FileOutputStream(Appearance.wallpaper(c))){out.write(wallpaper);}}else if(!had)Appearance.wallpaper(c).delete();}catch(IOException e){result.putString("restore_error","Wallpaper restore failed");}}
        finish(result.containsKey("error")||result.containsKey("restore_error")?Activity.RESULT_CANCELED:Activity.RESULT_OK,result);
    }
}
